import {RESOURCE_NAMES,sceneSnapshot,workDelay} from './living-world.js';
const tm=t=>String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');
export function renderComms(s,esc,expanded=true){const rows=(s.world?.feed||[]).slice(-25);return `<header><h2>值勤通訊</h2><div><button class="quiet" data-ui="effects">後續影響</button><button class="quiet" data-comms-toggle aria-expanded="${expanded}">${expanded?'收合':'展開'}</button></div></header>${expanded?`<div class="comms-messages" tabindex="0" aria-label="同事對話紀錄，捲動可看前文">${rows.length?rows.map(r=>`<article class="comms-row ${r.type.includes('影響')?'comms-effect':''}"><div><time>9/${15+r.day} ${tm(r.time)}</time><strong>${esc(r.actor)}</strong><span>${esc(r.type)}</span></div><p>${esc(r.text)}</p>${r.eventId?`<button class="quiet" data-open-event="${esc(r.cause||r.eventId)}">${r.cause?'查來源與後續':'查看這筆紀錄'} →</button>`:''}</article>`).join(''):'<p class="comms-empty">對講機已連線。接班後，各區同事會在這裡回報。</p>'}</div>`:`<button class="comms-latest" data-comms-toggle aria-label="展開值勤通訊">${rows.length?esc(rows.at(-1).actor+'：'+rows.at(-1).text):'等待各區回報'} →</button>`}${s.activeIncident?'<button class="comms-urgent" data-ui="incident">有新狀況待回應 · 時鐘已暫停 →</button>':''}`;}
export function effectsPanel(s,{header,c,esc}){header('先前安排帶來的後續','FOLLOW-UP');const w=s.world;c.innerHTML=`<p class="lead">回報不代表事情到此為止。人手、可用物資與設備安排會影響下一輪的工作時間與狀況。點紀錄可回查起因。</p><dl class="resource-list">${Object.entries(RESOURCE_NAMES).map(([id,label])=>`<div><dt>${label}</dt><dd>${w.resources[id]} / 100 <small>${workDelay(s,id)>0?'新狀況需多 '+workDelay(s,id)+' 分鐘':workDelay(s,id)<0?'新狀況可少 '+(-workDelay(s,id))+' 分鐘':'按原時間安排'}</small></dd></div>`).join('')}</dl><p class="monitor-note">這些是分工與調度的餘裕指標，不是設備的實測容量。新狀況安排時間以回應前顯示的估計為準；已開始的工作不會突然改期。</p><h3 class="section-title">等候後續確認</h3>${w.queue.length?'<ul class="help-list">'+w.queue.slice().sort((a,b)=>a.due-b.due).slice(0,14).map(q=>`<li>${esc(q.actor)}：${esc(q.title)} · 9/${15+Math.floor(q.due/1440)+1} ${tm(q.due%1440)} <button class="quiet" data-open-event="${esc(q.source)}">查原紀錄</button></li>`).join('')+'</ul>':'<p class="lead">目前沒有新的後續排程。</p>'}<p class="monitor-note">原事件的待追蹤項目仍須由承辦人處理；連帶影響出現不代表原事件自動結案。</p>`;}
export function sceneLabel(s){const v=sceneSnapshot(s);return `${{people:'同事工作中',empty:'目前無人在畫面內',anomaly:'現場有標示待查'}[v.kind]} · 每次前往重新觀察`}
